use dioxus_native::prelude::*;

/// Generated by `dx build`/`dx serve` from `tailwind.css`, then bundled by dx
/// under a content-hashed name.
const TAILWIND_CSS: Asset = asset!("/assets/tailwind.css");

fn main() {
    tracing_subscriber::fmt::init();
    install_crypto_provider();
    warn_if_unbundled();
    dioxus_native::launch(App);
}

/// Picks rustls's crypto backend for the whole process, once, before anything
/// builds a TLS client.
///
/// **Without it, joining a room at an `http://` relay panics.** That form fetches
/// the relay's certificate hash over plain HTTP with `reqwest`, which builds
/// its client on rustls's *process* default -- and there is none, because both
/// `aws-lc-rs` and `ring` are compiled into the tree, so rustls refuses to
/// guess. The panic is inside moq-native's reconnect task, so all that reached
/// the call was "reconnect stopped". moq-native's own TLS passes a provider
/// explicitly, which is why direct calls never hit this.
///
/// aws-lc-rs, to match the backend moq-native is built with.
fn install_crypto_provider() {
    if rustls::crypto::aws_lc_rs::default_provider()
        .install_default()
        .is_err()
    {
        // Only possible if something installed one first, which is fine.
        tracing::debug!("a rustls crypto provider was already installed");
    }
}

/// Complains if the app was built without dx, which leaves it unstyled.
///
/// `asset!` compiles to a placeholder only dx substitutes, and nothing
/// downstream treats the leftover as an error -- the resolver answers it with a
/// 404 whose *body* Blitz then parses as a stylesheet. Enabling dioxus-native's
/// `tracing` does not catch this; see README.
fn warn_if_unbundled() {
    if TAILWIND_CSS.to_string().contains("replaced by dx") {
        tracing::error!(
            "stylesheet was not bundled -- the window will be unstyled. \
             Build with `dx build --renderer native` or `dx serve --renderer native`."
        );
    }
}

#[component]
fn App() -> Element {
    camera::use_devices_provider();
    audio::use_microphones_provider();

    rsx! {
        document::Title { "Vdr "}
        document::Stylesheet { href: TAILWIND_CSS }
        // `h-screen`, not `h-full`: a percentage height on the root never
        // resolves in blitz -- checked on both the old pin and beta.4 -- and
        // without a definite height the video area cannot take what is left,
        // so the bar floats mid-window. `overflow-hidden` because nothing here
        // should ever scroll, and it stopped a one-pixel scrollbar flicker.
        div { class: "flex h-screen flex-col gap-4 overflow-hidden p-6",
            components::CallScreen {}
        }
    }
}
